using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed the discriminator property from
            // "Discriminator" to "$type". Preserve the old name so existing
            // documents and raw SQL queries (WHERE c.Discriminator = 'Blog') keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF 9 changed the id format from "EntityType|Key"
            // to just the key value. Preserve the old "Blog|{Id}" format so
            // existing documents remain addressable.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

// Generates ids in the legacy EF 8 format: "Blog|{key}"
class LegacyCosmosIdGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"Blog|{entry.Property("Id").CurrentValue}";
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

